export function filterHoldings(data,state){
 const q=(state.holdingQuery||'').trim().toLowerCase(),source=state.change==='disposed'?data.disposed:data.items;
 return source.filter(r=>r.kind===state.kind&&(state.change==='all'||r.changeType===state.change)&&(!q||(r.name+' '+(r.ticker||'')+' '+r.cusip).toLowerCase().includes(q))&&(!state.sector||r.sector===state.sector)&&[['weightMin',true,'weight'],['weightMax',false,'weight'],['valueMin',true,'value'],['valueMax',false,'value']].every(([k,min,type])=>{if(state[k]==null||state[k]==='')return true;const value=type==='weight'?(data.totalValue>0?r.valueUsd/data.totalValue*100:null):r.valueUsd;return Number.isFinite(value)&&(min?value>=Number(state[k]):value<=Number(state[k]));})).sort((a,b)=>{const metric=r=>state.sort==='change'?r.shareChangePct:state.sort==='month1'?r.priceChanges?.month1:state.sort==='month3'?r.priceChanges?.month3:r.valueUsd;const av=metric(a),bv=metric(b);return !Number.isFinite(av)?Number.isFinite(bv)?1:0:!Number.isFinite(bv)?-1:bv-av;});
}
